              "tour.welcome.body": "Tracy\u0020ch\u1ec9nh\u0020s\u1eeda\u0020website\u0020gi\u00fap\u0020b\u1ea1n.\u0020B\u1ea1n\u0020y\u00eau\u0020c\u1ea7u\u0020b\u1eb1ng\u0020l\u1eddi\u0020th\u01b0\u1eddng,\u0020ki\u1ec3m\u0020tra\u0020k\u1ebft\u0020qu\u1ea3\u0020r\u1ed3i\u0020xu\u1ea5t\u0020b\u1ea3n\u0020khi\u0020h\u00e0i\u0020l\u00f2ng.",
