              "tour.welcome.reviewBody": "Xem\u0020tr\u01b0\u1edbc\u0020tr\u00ean\u0020site\u0020c\u1ee7a\u0020b\u1ea1n",
              "tour.welcome.title": "Ch\u00e0o\u0020m\u1eebng\u0020b\u1ea1n\u0020\u0111\u1ebfn\u0020v\u1edbi\u0020Tracy",
              "welcome.1.title": "Ch\u00e0o\u0020m\u1eebng\u0020b\u1ea1n\u0020\u0111\u1ebfn\u0020v\u1edbi\u0020Tracy",
              "welcome.1.body": "C\u00e1ch\u0020nhanh\u0020h\u01a1n\u0020\u0111\u1ec3\u0020v\u1eadn\u0020h\u00e0nh\u0020website\u0020tr\u00ean\u0020CMS\u0020b\u1ea1n\u0020v\u1ed1n\u0020tin\u0020d\u00f9ng.\u0020B\u1ea5m\u0020v\u00e0o\u0020b\u1ea5t\u0020k\u1ef3\u0020ph\u1ea7n\u0020n\u00e0o\u0020tr\u00ean\u0020trang,\u0020n\u00f3i\u0020thay\u0020\u0111\u1ed5i\u0020b\u1ea1n\u0020mu\u1ed1n,\u0020th\u1ebf\u0020l\u00e0\u0020xong.\u0020Kh\u00f4ng\u0020c\u1ea7n\u0020m\u1edf\u0020trang\u0020admin\u0020c\u1ee7a\u0020Joomla\u0020hay\u0020WordPress.",
              "welcome.2.title": "Mang\u0020site\u0020s\u1eb5n\u0020c\u00f3\u0020c\u1ee7a\u0020b\u1ea1n\u0020v\u00e0o",
              "welcome.2.body": "D\u00e1n\u0020\u0111\u1ecba\u0020ch\u1ec9\u0020c\u1ee7a\u0020b\u1ea1n,\u0020Tracy\u0020s\u1ebd\u0020t\u1ea1o\u0020m\u1ed9t\u0020b\u1ea3n\u0020sao\u0020\u0111\u1ec3\u0020l\u00e0m\u0020vi\u1ec7c.\u0020Site\u0020th\u1eadt\u0020v\u1eabn\u0020ch\u1ea1y\u0020b\u00ecnh\u0020th\u01b0\u1eddng\u0020trong\u0020l\u00fac\u0020b\u1ea1n\u0020s\u1eeda,\u0020v\u00e0\u0020b\u1ea1n\u0020g\u1eedi\u0020thay\u0020\u0111\u1ed5i\u0020sang\u0020b\u1ea5t\u0020c\u1ee9\u0020khi\u0020n\u00e0o\u0020s\u1eb5n\u0020s\u00e0ng.\u0020Kh\u00f4ng\u0020c\u1ea7n\u0020ch\u1ebf\u0020\u0111\u1ed9\u0020b\u1ea3o\u0020tr\u00ec.",
              "welcome.3.title": "B\u1eaft\u0020\u0111\u1ea7u\u0020t\u1eeb\u0020template\u0020mi\u1ec5n\u0020ph\u00ed",
              "welcome.3.body": "Ch\u01b0a\u0020c\u00f3\u0020site?\u0020Kh\u00e1m\u0020ph\u00e1\u0020th\u01b0\u0020vi\u1ec7n\u0020l\u1edbn\u0020g\u1ed3m\u0020c\u00e1c\u0020template\u0020mi\u1ec5n\u0020ph\u00ed\u0020cho\u0020m\u1ecdi\u0020lo\u1ea1i\u0020h\u00ecnh\u0020kinh\u0020doanh.\u0020Xem\u0020preview\u0020c\u1ee7a\u0020b\u1ea5t\u0020k\u1ef3\u0020template\u0020n\u00e0o\u0020\u1edf\u0020ch\u1ebf\u0020\u0111\u1ed9\u0020s\u00e1ng,\u0020t\u1ed1i\u0020ho\u1eb7c\u0020tr\u00ean\u0020\u0111i\u1ec7n\u0020tho\u1ea1i,\u0020r\u1ed3i\u0020d\u1ef1ng\u0020site\u0020c\u1ee7a\u0020b\u1ea1n\u0020t\u1eeb\u0020\u0111\u00f3.",
              "welcome.4.title": "\u0110\u1ed5i\u0020di\u1ec7n\u0020m\u1ea1o\u0020v\u1edbi\u00201.200+\u0020phong\u0020c\u00e1ch",
              "welcome.4.body": "Kh\u00e1m\u0020ph\u00e1\u0020h\u01a1n\u00201.200\u0020h\u1ec7\u0020thi\u1ebft\u0020k\u1ebf\u0020l\u1ea5y\u0020c\u1ea3m\u0020h\u1ee9ng\u0020t\u1eeb\u0020nh\u1eefng\u0020s\u1ea3n\u0020ph\u1ea9m\u0020nh\u01b0\u0020Figma\u0020hay\u0020ElevenLabs.\u0020Ch\u1ecdn\u0020m\u1ed9t\u0020h\u1ec7,\u0020Tracy\u0020s\u1ebd\u0020l\u00e0m\u0020m\u1edbi\u0020m\u1ecdi\u0020trang\u0020b\u1eb1ng\u0020m\u00e0u\u0020s\u1eafc,\u0020font\u0020ch\u1eef\u0020v\u00e0\u0020kho\u1ea3ng\u0020c\u00e1ch\u0020c\u1ee7a\u0020h\u1ec7\u0020\u0111\u00f3.",
              "welcome.5.title": "Bi\u1ebfn\u0020b\u1ea3n\u0020m\u00f4\u0020t\u1ea3\u0020th\u00e0nh\u0020site",
              "welcome.5.body": "Cho\u0020Tracy\u0020bi\u1ebft\u0020t\u00ean\u0020doanh\u0020nghi\u1ec7p,\u0020l\u0129nh\u0020v\u1ef1c,\u0020ng\u00f4n\u0020ng\u1eef,\u0020gi\u1ecdng\u0020v\u0103n\u0020v\u00e0\u0020logo\u0020c\u1ee7a\u0020b\u1ea1n.\u0020Tracy\u0020vi\u1ebft\u0020m\u1ecdi\u0020trang\u0020v\u00e0\u0020t\u1ea1o\u0020\u1ea3nh\u0020ph\u00f9\u0020h\u1ee3p:\u0020m\u1ed9t\u0020site\u0020g\u1ea7n\u0020nh\u01b0\u0020ho\u00e0n\u0020ch\u1ec9nh,\u0020kh\u00f4ng\u0020ph\u1ea3i\u0020b\u1ea3n\u0020demo\u0020ph\u1ea3i\u0020\u0111i\u1ec1n\u0020t\u1eebng\u0020d\u00f2ng.",
              "welcome.6.title": "M\u1eddi\u0020\u0111\u1ed9i\u0020ng\u0169,\u0020ph\u00e2n\u0020quy\u1ec1n\u0020truy\u0020c\u1eadp",
              "welcome.6.body": "M\u1eddi\u0020m\u1ecdi\u0020ng\u01b0\u1eddi\u0020v\u00e0o\u0020site\u0020v\u00e0\u0020giao\u0020cho\u0020m\u1ed7i\u0020ng\u01b0\u1eddi\u0020m\u1ed9t\u0020vai\u0020tr\u00f2:\u0020Ng\u01b0\u1eddi\u0020ch\u1ec9nh\u0020s\u1eeda\u0020\u0111\u1ec3\u0020th\u1ef1c\u0020hi\u1ec7n\u0020thay\u0020\u0111\u1ed5i,\u0020Ng\u01b0\u1eddi\u0020xem\u0020\u0111\u1ec3\u0020xem\u0020v\u00e0\u0020theo\u0020d\u00f5i.\u0020B\u1ea5m\u0020v\u00e0o\u0020b\u1ea5t\u0020k\u1ef3\u0020ph\u1ea7n\u0020n\u00e0o\u0020tr\u00ean\u0020trang\u0020\u0111\u1ec3\u0020ghi\u0020ch\u00fa\u0020v\u00e0\u0020g\u1eafn\u0020th\u1ebb\u0020h\u1ecd\u0020b\u1eb1ng\u0020@.",
              "welcome.7.title": "Xem\u0020v\u00e0\u0020ho\u00e0n\u0020t\u00e1c\u0020m\u1ecdi\u0020thay\u0020\u0111\u1ed5i",
              "welcome.7.body": "M\u1ecdi\u0020thay\u0020\u0111\u1ed5i\u0020\u0111\u1ec1u\u0020\u0111\u01b0\u1ee3c\u0020l\u01b0u\u0020trong\u0020Thay\u0020\u0111\u1ed5i\u0020c\u1ee7a\u0020site,\u0020k\u00e8m\u0020ng\u01b0\u1eddi\u0020th\u1ef1c\u0020hi\u1ec7n\u0020v\u00e0\u0020th\u1eddi\u0020\u0111i\u1ec3m.\u0020M\u1edf\u0020m\u1ed9t\u0020thay\u0020\u0111\u1ed5i\u0020\u0111\u1ec3\u0020xem\u0020\u0111\u00e3\u0020\u0111\u1ed5i\u0020g\u00ec,\u0020ho\u1eb7c\u0020\u0111\u01b0a\u0020c\u1ea3\u0020site\u0020v\u1ec1\u0020m\u1ed9t\u0020phi\u00ean\u0020b\u1ea3n\u0020tr\u01b0\u1edbc\u0020\u0111\u00f3.",
              "welcome.8.title": "L\u00ean\u0020s\u00f3ng\u0020theo\u0020c\u00e1ch\u0020c\u1ee7a\u0020b\u1ea1n",
              "welcome.8.body": "\u0110\u01b0a\u0020site\u0020l\u00ean\u0020m\u1ea1ng\u0020ngay\u0020tr\u00ean\u0020Tracy\u0020ch\u1ec9\u0020v\u1edbi\u0020m\u1ed9t\u0020c\u00fa\u0020b\u1ea5m\u0020v\u00e0\u0020g\u1eafn\u0020domain\u0020ri\u00eang.\u0020Site\u0020c\u1ee7a\u0020b\u1ea1n\u0020\u0111\u01b0\u1ee3c\u0020nh\u1eadp\u0020t\u1eeb\u0020n\u01a1i\u0020kh\u00e1c?\u0020G\u1eedi\u0020thay\u0020\u0111\u1ed5i\u0020ng\u01b0\u1ee3c\u0020v\u1ec1\u0020hosting\u0020hi\u1ec7n\u0020t\u1ea1i.\u0020Ho\u1eb7c\u0020download\u0020b\u1ea3n\u0020ZIP\u0020\u0111\u1ec3\u0020\u0111\u1eb7t\u0020\u1edf\u0020b\u1ea5t\u0020c\u1ee9\u0020\u0111\u00e2u.",
